('56d30057-52bf-4583-985a-815cc6c60d28', 'Photography', 'Capture the Moment', 'Professional cameras, lenses, and accessories for both enthusiasts and professional photographers.', 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?q=80&w=2000&auto=format&fit=crop', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('a38cadad-4fc9-4508-8fc8-e0ab590eee62', 'Wearables', 'Smart Fashion', 'Track your health and stay in style with our premium selection of smartwatches and fitness trackers.', 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?q=80&w=1999&auto=format&fit=crop', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('af273e65-172f-4b32-b15c-3342acec34d1', 'Electronics', 'Next-Generation Tech', 'Explore the latest in high-performance electronics, designed to keep you connected and productive.', 'https://images.unsplash.com/photo-1498049794561-7780e7231661?q=80&w=2070&auto=format&fit=crop', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('e758c2f5-88dd-4c71-88ba-206c3f20f197', 'Furniture', 'Modern Living', 'Upgrade your workspace and home with our ergonomic and modern furniture collection.', 'https://images.unsplash.com/photo-1505843490538-5133c6c7d0e1?q=80&w=2069&auto=format&fit=crop', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('fbf21cc3-ee21-48cb-8cf3-933b3b22f01b', 'Accessories', 'The Perfect Additions', 'Enhance your daily setup with premium bags, wallets, cases, and input devices.', 'https://images.unsplash.com/photo-1627123424574-724758594e93?q=80&w=2000&auto=format&fit=crop', '2026-08-17 11:46:03', '2026-08-17 11:46:03');
INSERT INTO `Products` (`id`, `name`, `slug`, `sku`, `image`, `description`, `category`, `price`, `sellPrice`, `stock`, `allowSellWithoutStock`, `images`, `keypoints`, `variations`, `longDescription`, `faq`, `tags`, `imageTextSections`, `status`, `createdAt`, `updatedAt`) VALUES 
('016a29b5-de50-4654-bca6-019c948f8105', 'Aero XR Smart Glasses', NULL, NULL, 'https://images.unsplash.com/photo-1573455494060-c5595004fb6c?q=80&w=2040&auto=format&fit=crop', 'Augmented reality smart glasses that project a 120-inch virtual screen before your eyes for immersive media consumption.', 'Wearables', '599.00', NULL, 0, 0, '["https://images.unsplash.com/photo-1573455494060-c5595004fb6c?q=80&w=2040&auto=format&fit=crop"]', '["Micro-OLED dual displays","120-inch virtual screen equivalent","Built-in directional speakers","USB-C DisplayPort support"]', '[{"name":"Frame Style","options":["Wayfarer","Aviator"]}]', '<h1>A Theater on Your Face</h1><p>Experience movies and gaming like never before. The Aero XR glasses plug directly into your smartphone or console and project a massive, crisp virtual display directly into your field of vision.</p>', '[{"a":"No, they weigh only 79 grams and are comfortable for hours of use.","q":"Are they heavy?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('027b3c99-c02c-481d-956a-e68a337609cd', 'Zenith Minimalist Smartwatch', NULL, NULL, 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?q=80&w=1999&auto=format&fit=crop', 'A masterpiece of wearable technology that looks like a traditional mechanical watch but houses advanced health tracking and GPS.', 'Wearables', '249.00', '199.50', 60, 0, '["https://images.unsplash.com/photo-1523275335684-37898b6baf30?q=80&w=1999&auto=format&fit=crop","https://images.unsplash.com/photo-1434494878577-86c23bcb06b9?q=80&w=2070&auto=format&fit=crop"]', '["Continuous Heart Rate Tracking","Blood Oxygen (SpO2) sensor","Built-in GPS","5ATM water resistance","14-day battery life"]', '[{"name":"Case Color","options":["Brushed Steel","Matte Black"]},{"name":"Strap Material","options":["Leather","Silicone"]}]', '<h1>Classic Aesthetics, Modern Intelligence</h1><p>The Zenith Smartwatch bridges the gap between classic horology and modern fitness tracking. Designed for those who want health data without sacrificing style, it features an always-on AMOLED display hidden beneath a traditional analog face.</p><h2>Comprehensive Health Tracking</h2><p>Monitor your sleep stages, stress levels, heart rate, and blood oxygen 24/7 without needing to charge every night.</p>', '[{"a":"Yes, the 5ATM rating means it is safe for showering and surface swimming.","q":"Can I shower with it?"},{"a":"Yes, via NFC.","q":"Does it support contactless payments?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('2310f0bd-680b-4a84-b36b-0bc5557a97da', 'Velocity Portable SSD 1TB', NULL, NULL, 'https://images.unsplash.com/photo-1597848212624-a19eb35e2651?q=80&w=1964&auto=format&fit=crop', 'Ultra-fast NVMe portable solid-state drive with read speeds up to 1050MB/s, housed in a rugged aluminum enclosure.', 'Electronics', '149.99', '119.99', 120, 0, '["https://images.unsplash.com/photo-1597848212624-a19eb35e2651?q=80&w=1964&auto=format&fit=crop"]', '["1TB Storage Capacity","Up to 1050MB/s read speeds","USB-C 3.2 Gen 2","Drop-resistant up to 2 meters","Hardware encryption"]', '[{"name":"Capacity","options":["1TB","2TB","4TB"]}]', '<h1>Speed That Keeps Up With You</h1><p>Transfer massive files in seconds with the Velocity Portable SSD. Utilizing NVMe technology, this drive offers blazing fast speeds in a form factor small enough to fit in your coin pocket.</p>', '[{"a":"Yes, it comes formatted in exFAT to work seamlessly across both platforms.","q":"Is it compatible with Mac and PC?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('30720968-5c16-41a8-853b-bbb0ed9872f6', 'Nimbus Wireless ANC Headphones', NULL, NULL, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?q=80&w=2070&auto=format&fit=crop', 'Immersive high-fidelity audio with adaptive active noise cancellation and an impressive 40-hour battery life.', 'Electronics', '299.99', '249.99', 45, 0, '["https://images.unsplash.com/photo-1505740420928-5e560c06d30e?q=80&w=2070&auto=format&fit=crop","https://images.unsplash.com/photo-1524678606370-a47ad25cb82a?q=80&w=2069&auto=format&fit=crop"]', '["Adaptive Active Noise Cancellation","40-hour battery life","Bluetooth 5.2","Multipoint connection","Spatial Audio support"]', '[{"name":"Color","options":["Matte Black","Lunar Silver","Midnight Blue"]}]', '<h1>Silence the World, Elevate Your Music</h1><p>Experience unparalleled sound quality with the Nimbus Wireless Headphones. Designed for audiophiles and commuters alike, these headphones deliver crystal clear highs and deep, resonant bass, all while intelligently blocking out environmental noise.</p><h2>All-Day Comfort</h2><p>Featuring memory foam earcups wrapped in breathable protein leather, you can listen for hours without fatigue.</p>', '[{"a":"A full charge takes approximately 2 hours, but a quick 10-minute charge gives you 4 hours of playback.","q":"How long does it take to charge?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('30fda444-6710-4c9a-b352-31c4ed2a623c', 'Aura Pro 4K Monitor', NULL, NULL, 'https://images.unsplash.com/photo-1527443224154-c4a3942d4aff?q=80&w=2070&auto=format&fit=crop', 'Stunning 27-inch 4K UHD display engineered for creative professionals with a 99% sRGB color gamut and incredibly thin bezels.', 'Electronics', '499.00', '429.99', 25, 0, '["https://images.unsplash.com/photo-1527443224154-c4a3942d4aff?q=80&w=2070&auto=format&fit=crop","https://images.unsplash.com/photo-1616423640778-28d1b53229bd?q=80&w=2070&auto=format&fit=crop"]', '["27-inch IPS panel","4K UHD (3840 x 2160)","99% sRGB color gamut","AMD FreeSync Premium","USB-C Power Delivery (65W)"]', '[]', '<h1>Uncompromising Visual Brilliance</h1><p>See every detail in stunning 4K clarity. Perfect for creative professionals, avid gamers, and anyone who refuses to compromise on visual fidelity. The Aura Pro 4K Monitor features a vibrant IPS panel with factory-calibrated color accuracy right out of the box.</p><h2>Seamless Connectivity</h2><p>Declutter your desk with single-cable USB-C connectivity that delivers video, data, and up to 65W of power to your laptop simultaneously.</p>', '[{"a":"Yes, it supports standard 100x100mm VESA mounting.","q":"Does it come with a VESA mount?"},{"a":"The monitor operates at 60Hz natively.","q":"What is the refresh rate?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('43c89d39-5e29-4738-89e2-3ad8eb41ea41', 'ErgoPro Executive Desk Chair', NULL, NULL, 'https://images.unsplash.com/photo-1505843490538-5133c6c7d0e1?q=80&w=2069&auto=format&fit=crop', 'Designed for ultimate comfort during long work sessions, featuring dynamic lumbar support, breathable mesh, and 4D armrests.', 'Furniture', '349.00', '299.00', 12, 0, '["https://images.unsplash.com/photo-1505843490538-5133c6c7d0e1?q=80&w=2069&auto=format&fit=crop","https://images.unsplash.com/photo-1598300042247-d088f8ab3a91?q=80&w=1965&auto=format&fit=crop"]', '["Dynamic auto-adjusting lumbar support","Premium breathable Korean mesh","4D adjustable armrests","Aluminum alloy base","Weight capacity: 300 lbs"]', '[{"name":"Color","options":["Graphite Black","Ash Grey","Navy Blue"]}]', '<h1>Sit Better, Work Better</h1><p>Say goodbye to back pain. The ErgoPro Executive chair adapts to your movements, providing continuous support whether you are leaning forward to type or reclining to take a call. The high-tension mesh prevents heat buildup.</p><h2>Fully Customizable Fit</h2><p>With 11 points of adjustment, you can tailor this chair to perfectly fit your unique body geometry.</p>', '[{"a":"It requires minimal assembly (about 15 minutes). Tools are included.","q":"Does it come assembled?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('4a4be09f-6788-4df2-a5ed-20fb9c010355', 'Pulse Active Fitness Band', NULL, NULL, 'https://images.unsplash.com/photo-1576243345690-4e4b79b63288?q=80&w=2070&auto=format&fit=crop', 'An ultra-lightweight fitness tracker that provides accurate metrics for over 50 sports, perfect for the dedicated athlete.', 'Wearables', '79.99', NULL, 150, 0, '["https://images.unsplash.com/photo-1576243345690-4e4b79b63288?q=80&w=2070&auto=format&fit=crop"]', '["1.4-inch AMOLED display","50+ sports modes","Sleep quality scoring","Lightweight design (18g)","10-day battery"]', '[{"name":"Color","options":["Onyx Black","Coral Pink","Mint Green"]}]', '<h1>Your Personal Coach</h1><p>Keep track of every step, run, and swim with the Pulse Active. Its unobtrusive design ensures it never gets in the way of your workout.</p>', '[{"a":"You need a smartphone for the initial setup and detailed data analysis via the companion app.","q":"Does it require a smartphone?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('4d2c3fce-737c-403c-a712-5d3bc20af7c8', 'Nomad Premium Leather Wallet', NULL, NULL, 'https://images.unsplash.com/photo-1627123424574-724758594e93?q=80&w=2000&auto=format&fit=crop', 'A handcrafted, minimalist front-pocket wallet made from full-grain Horween leather that develops a beautiful patina over time.', 'Accessories', '65.00', NULL, 80, 0, '["https://images.unsplash.com/photo-1627123424574-724758594e93?q=80&w=2000&auto=format&fit=crop"]', '["Full-grain Horween leather","Holds up to 8 cards and cash","RFID-blocking inner layer","Hand-stitched durability"]', '[{"name":"Color","options":["Rustic Brown","Midnight Black","English Tan"]}]', '<h1>A Wallet That Ages With You</h1><p>Crafted in the USA from premium leather sourced from one of the oldest tanneries in the country. This wallet will mold to your pocket and develop a rich patina that tells the story of your travels.</p>', '[]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('524270d0-1a89-472b-a2a7-08d166ca4e21', 'Echo Pod Smart Speaker', NULL, NULL, 'https://images.unsplash.com/photo-1558089687-f282ffcbc126?q=80&w=2071&auto=format&fit=crop', 'Control your entire smart home, stream music, and get answers instantly with this voice-activated hub featuring room-filling sound.', 'Electronics', '129.50', NULL, 80, 0, '["https://images.unsplash.com/photo-1558089687-f282ffcbc126?q=80&w=2071&auto=format&fit=crop"]', '["Room-filling 360-degree sound","Built-in voice assistant","Smart home hub capabilities","Privacy microphone disconnect"]', '[{"name":"Color","options":["Charcoal","Glacier White"]}]', '<h1>The Center of Your Smart Home</h1><p>The Echo Pod is more than just a speaker. It is a central hub that connects all your smart devices. With a customized acoustic architecture, it delivers rich, detailed sound that adapts to the acoustics of your room.</p>', '[{"a":"Yes, it supports Spotify, Apple Music, Amazon Music, and more.","q":"Does it work with Apple Music?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('7075dd29-0a04-4b8f-9002-762d1344bb99', 'Aero Wireless Gaming Mouse', NULL, NULL, 'https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?q=80&w=2067&auto=format&fit=crop', 'An ultra-lightweight 60-gram wireless mouse featuring a flawless 25K DPI sensor and PTFE glide skates for precision tracking.', 'Accessories', '89.99', '69.99', 40, 0, '["https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?q=80&w=2067&auto=format&fit=crop"]', '["60g ultra-lightweight design","25,000 max DPI sensor","Optical switches (0.2ms response)","Virgin-grade PTFE feet"]', '[{"name":"Color","options":["Matte Black","Matte White"]}]', '<h1>Speed and Precision</h1><p>Dominate your competitive matches. By stripping away unnecessary weight and utilizing lightning-fast optical switches, the Aero mouse translates your reflexes into in-game actions with zero lag.</p>', '[{"a":"Yes, via the included paracord USB-C cable. You can use it while it charges.","q":"Is the battery rechargeable?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('8db804ac-57e5-4d49-8dde-1608d2352868', 'Nordic Lounge Sofa', NULL, NULL, 'https://images.unsplash.com/photo-1493663284031-b7e3aefcae8e?q=80&w=2070&auto=format&fit=crop', 'A minimalist 3-seater sofa inspired by Scandinavian design, featuring premium linen upholstery and solid oak legs.', 'Furniture', '899.00', NULL, 4, 0, '["https://images.unsplash.com/photo-1493663284031-b7e3aefcae8e?q=80&w=2070&auto=format&fit=crop"]', '["Premium Linen blend upholstery","High-density foam cushions","Solid kiln-dried oak frame","Seats 3 comfortably"]', '[{"name":"Color","options":["Oatmeal","Charcoal","Olive"]}]', '<h1>Timeless Comfort</h1><p>The Nordic Lounge Sofa brings understated elegance to any living room. The deep seats and high-density foam offer sink-in comfort that retains its shape over years of use.</p>', '[{"a":"The seat and back cushion covers are removable and machine washable on a gentle, cold cycle.","q":"Are the cushion covers washable?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('8e685aa3-a911-4652-aed4-0bdf9b98cfec', 'Hydro Thermal Flask', NULL, NULL, 'https://images.unsplash.com/photo-1602143407151-7111542de6e8?q=80&w=1974&auto=format&fit=crop', 'A 32oz double-wall vacuum insulated stainless steel water bottle that keeps beverages ice cold for 24 hours.', 'Accessories', '34.99', NULL, 120, 0, '["https://images.unsplash.com/photo-1602143407151-7111542de6e8?q=80&w=1974&auto=format&fit=crop"]', '["18/8 Pro-Grade Stainless Steel","Double-wall vacuum insulation","Sweat-free powder coat finish","BPA-Free"]', '[{"name":"Color","options":["Ocean Blue","Forest Green","Lava Red","Graphite"]}]', '<h1>Hydration on the Go</h1><p>Whether you\'re hiking a mountain or sitting at a desk, the Hydro Thermal Flask ensures your water stays perfectly chilled. The proprietary powder coat prevents condensation, keeping your hands and bag dry.</p>', '[{"a":"Yes, the flask and lid are top-rack dishwasher safe.","q":"Is it dishwasher safe?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('942d94ea-073d-4e35-879e-e38a1e007246', 'Aero Drone Pro', NULL, NULL, 'https://images.unsplash.com/photo-1507582020474-9a35b7d455d9?q=80&w=2070&auto=format&fit=crop', 'A compact, foldable drone featuring a Hasselblad camera, omnidirectional obstacle sensing, and 45 minutes of flight time.', 'Photography', '899.00', '849.00', 10, 0, '["https://images.unsplash.com/photo-1507582020474-9a35b7d455d9?q=80&w=2070&auto=format&fit=crop"]', '["20MP 1-inch CMOS Sensor","5.4K/30fps Video","Omnidirectional Obstacle Sensing","12km Video Transmission","45-minute flight time"]', '[{"name":"Package","options":["Standard","Fly More Combo (3 Batteries)"]}]', '<h1>Capture The World From Above</h1><p>The Aero Drone Pro puts professional aerial cinematography in a backpack-friendly form factor. Master shots feature automates complex flight paths so you can focus on directing.</p>', '[{"a":"It weighs over 250g, so registration with local aviation authorities (like the FAA) is required in many countries.","q":"Do I need a license to fly this?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('949e2490-ffdd-4108-9d3a-e2d311052f01', 'Carbon Fiber Tripod', NULL, NULL, 'https://images.unsplash.com/photo-1589578228447-e1a4e481c6c8?q=80&w=1964&auto=format&fit=crop', 'An ultra-light, extremely rigid carbon fiber tripod with a 360-degree panoramic ball head. Folds down to just 15 inches.', 'Photography', '199.00', NULL, 25, 0, '["https://images.unsplash.com/photo-1589578228447-e1a4e481c6c8?q=80&w=1964&auto=format&fit=crop"]', '["10-layer carbon fiber tubes","Folds to 15.3 inches","Max height of 62 inches","Load capacity: 22 lbs","Arca-Swiss compatible ball head"]', '[]', '<h1>The Traveler\'s Best Friend</h1><p>Don\'t let a heavy tripod weigh you down on your hikes. This carbon fiber tripod provides rock-solid stability for long exposures in windy conditions, while remaining incredibly light to carry.</p>', '[]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('b9140302-a254-40ae-869f-8e8e321cb361', 'Prime 50mm f/1.4 Lens', NULL, NULL, 'https://images.unsplash.com/photo-1617005082833-1eb58574108c?q=80&w=1964&auto=format&fit=crop', 'The essential "nifty fifty" prime lens, featuring an ultra-fast f/1.4 aperture for stunning bokeh and low-light performance.', 'Photography', '599.00', NULL, 14, 0, '["https://images.unsplash.com/photo-1617005082833-1eb58574108c?q=80&w=1964&auto=format&fit=crop"]', '["f/1.4 maximum aperture","9-blade circular aperture diaphragm","Nano AR Coating","Silent autofocus motor"]', '[{"name":"Mount","options":["Sony E","Canon RF","Nikon Z"]}]', '<h1>The Storyteller\'s Lens</h1><p>Render your subjects with razor-sharp clarity against beautifully blurred backgrounds. This 50mm lens is a must-have for portraits, street photography, and low-light environments.</p>', '[{"a":"No, this lens relies on your camera\'s In-Body Image Stabilization (IBIS).","q":"Does it have optical stabilization?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('d7c87daf-55c2-4cd1-86b3-b5dd6942e473', 'Nexus Mechanical Keyboard', NULL, NULL, 'https://images.unsplash.com/photo-1595225476474-87563907a212?q=80&w=2071&auto=format&fit=crop', 'A premium wireless mechanical keyboard with tactile switches, PBT keycaps, and a stunning solid aluminum chassis.', 'Accessories', '149.99', '119.99', 32, 0, '["https://images.unsplash.com/photo-1595225476474-87563907a212?q=80&w=2071&auto=format&fit=crop"]', '["Hot-swappable tactile switches","Tri-mode (Bluetooth, 2.4GHz, USB-C)","Double-shot PBT keycaps","Mac/Windows compatible","Customizable RGB"]', '[{"name":"Switch Type","options":["Tactile (Brown)","Linear (Red)","Clicky (Blue)"]},{"name":"Layout","options":["75%","100% Full Size"]}]', '<h1>The Ultimate Typing Experience</h1><p>Every keystroke feels incredibly satisfying. The hot-swappable PCB allows you to change switches without soldering, making it the perfect gateway into the world of custom keyboards.</p>', '[{"a":"Up to 72 hours with RGB on, and over 200 hours with RGB off.","q":"How long does the battery last on wireless?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('dff0a925-8394-471b-b399-9e998e48a35f', 'Titanium Smart Ring', NULL, NULL, 'https://images.unsplash.com/photo-1605518216938-7c31b7b14ad0?q=80&w=2009&auto=format&fit=crop', 'Discreet, highly accurate health tracking packed into a sleek aerospace-grade titanium ring.', 'Wearables', '299.00', '275.00', 35, 0, '["https://images.unsplash.com/photo-1605518216938-7c31b7b14ad0?q=80&w=2009&auto=format&fit=crop"]', '["Aerospace-grade titanium","Advanced sleep tracking","Temperature sensors","7-day battery life"]', '[{"name":"Finish","options":["Silver","Stealth Black","Gold"]},{"name":"Size","options":["Size 8","Size 9","Size 10","Size 11"]}]', '<h1>Invisibly Smart</h1><p>Don\'t like wearing watches to bed? The Titanium Smart Ring provides clinical-grade sleep and recovery metrics from your finger, offering more accurate pulse readings than wrist-based trackers.</p>', '[{"a":"We recommend visiting a local jeweler to confirm your standard US ring size before ordering.","q":"How do I know my size?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('e5238026-6aa1-4a47-ba56-434ba5fbb34a', 'Apex Standing Desk', NULL, NULL, 'https://images.unsplash.com/photo-1595515106969-1ce29566ff1c?q=80&w=2070&auto=format&fit=crop', 'A dual-motor electric standing desk with a solid wood top and memory presets for seamless transitions between sitting and standing.', 'Furniture', '499.00', '449.00', 8, 0, '["https://images.unsplash.com/photo-1595515106969-1ce29566ff1c?q=80&w=2070&auto=format&fit=crop"]', '["Dual electric motors","Solid bamboo or walnut top","4 programmable height presets","Anti-collision technology","Supports up to 220 lbs"]', '[{"name":"Wood Type","options":["Bamboo","Walnut","Oak"]},{"name":"Size","options":["48-inch","60-inch"]}]', '<h1>Elevate Your Workspace</h1><p>Transition seamlessly from sitting to standing with the push of a button. The Apex Standing Desk features whisper-quiet dual motors and a rock-solid steel frame to ensure absolute stability even at its highest setting.</p>', '[{"a":"Yes, our bamboo tops are 100% sustainable and FSC certified.","q":"Is the wood sustainably sourced?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('eb2056b5-c58f-4b5f-89e7-0d3108168e55', 'Aura Ambient Floor Lamp', NULL, NULL, 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?q=80&w=2070&auto=format&fit=crop', 'A sleek, minimalist LED floor lamp that bathes your room in customizable, diffused RGB light.', 'Furniture', '129.99', NULL, 22, 0, '["https://images.unsplash.com/photo-1507473885765-e6ed057f782c?q=80&w=2070&auto=format&fit=crop"]', '["16 million colors","Dimmable via smartphone app","Corner-fit minimalist design","Syncs with music"]', '[{"name":"Finish","options":["Black","White"]}]', '<h1>Paint Your Room With Light</h1><p>Designed to fit perfectly into the corner of your room, the Aura Ambient lamp reflects light off your walls to create a stunning, atmospheric glow without taking up floor space.</p>', '[]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03'),
('fa2fa83c-6ac0-49d9-b48f-2df0027e18cc', 'Lumina X1 Mirrorless Camera', NULL, NULL, 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?q=80&w=2000&auto=format&fit=crop', 'A professional-grade full-frame mirrorless camera offering 45 Megapixels, 8K video recording, and advanced subject tracking autofocus.', 'Photography', '1499.00', '1399.00', 5, 0, '["https://images.unsplash.com/photo-1516035069371-29a1b244cc32?q=80&w=2000&auto=format&fit=crop","https://images.unsplash.com/photo-1502920917128-1aa500764cbd?q=80&w=2070&auto=format&fit=crop"]', '["45MP Full-Frame CMOS Sensor","8K RAW Video Recording","In-Body Image Stabilization (IBIS)","AI-driven Autofocus","Weather-sealed alloy body"]', '[{"name":"Kit","options":["Body Only","With 24-70mm f/2.8 Lens"]}]', '<h1>The Ultimate Creative Tool</h1><p>Whether you are shooting high-fashion portraits or cinematic documentaries, the Lumina X1 delivers uncompromising image quality. Its revolutionary autofocus system locks onto eyes, faces, and animals with terrifying precision.</p><h2>Robust and Reliable</h2><p>Constructed from magnesium alloy and heavily weather-sealed, it is built to withstand the harshest shooting conditions.</p>', '[{"a":"It can record 8K video continuously for up to 45 minutes before thermal limits are reached at room temperature.","q":"Does it overheat during 8K recording?"}]', NULL, NULL, 'published', '2026-08-17 11:46:03', '2026-08-17 11:46:03');
